-- Snapshot of the prototype schema and data (before migration 001/002).
CREATE TABLE billing_details (
	ID INTEGER PRIMARY KEY AUTOINCREMENT,
	STUDENT_ID INTEGER,
	STUDENT_CLASS TEXT,
	NOTES TEXT,
	PAID_ON TEXT,
	AMOUNT_PAID REAL,
	PAYMENT_METHOD TEXT,
	PAYMENT_NOTES TEXT,
	BALANCE_AMOUNT_TO_PAY REAL,
	INSERTED_ON TEXT,
	UPDATED_ON TEXT
, AMOUNT_IN_WORDS TEXT, BILLING_NAME TEXT, BILLING_TYPE text);
