CREATE TABLE "fee_structure_yearly" (
	ID INTEGER PRIMARY KEY AUTOINCREMENT,
	STUDENT_CLASS TEXT,
	START_DATE TEXT,
	END_DATE TEXT,
	IS_ACTIVE INTEGER DEFAULT (1),
	AMOUNT_TO_PAY REAL DEFAULT (0),
	INSERTED_ON TEXT,
	UPDATED_ON TEXT
);
