CREATE TABLE guardian_details (
	ID INTEGER PRIMARY KEY AUTOINCREMENT,
	NAME TEXT,
	RELATION_TYPE TEXT,
	MOBILE_NUMBER TEXT,
	YEAR_OF_BIRTH INTEGER,
	STUDENT_IDS BLOB
, STUDENT_ID INTEGER);
