CREATE TABLE identifier_table (
	ID TEXT,
	IDENTIFIER_TYPE TEXT,
	IDENTIFIER_VALUE_AES TEXT,
	LAST_4_DIGIT_OF_IDENTIFIER TEXT,
	NOUNCE TEXT
, TAG TEXT);
